            "CallExpression:exit"(node) {
                if (!isTestCall(node)) {
                    return;
                }
                const { count } = openTests.pop();
                if (count > max) {
                    context.report({
                        node,
                        messageId: "tooManyExpects",
                        data: { count, max },
                    });
                }
            },
        };
    },
};

